const $tabelData = $('#tabelData'),
    $formData = $('#formData'),
    $modalDiv = $('#modalDiv'),
    formCek = CirebonwebForm.FormCek($formData);

$(function () {
    $tabelData.DataTable({
        processing: true,
        serverSide: true,
        ajax: {
            url: `${urlThis}/tabel`,
            type: 'POST',
            data: function (d) {
                d.filter_kondisi = $('#filter_kondisi').val();
                d.filter_status = $('#filter_status').val();
            }
        },
        autoWidth: false,
        responsive: true,
        search: { return: true },
        dom: 'Blfrtip',
        buttons: [
            {
                text: 'Reload',
                action: function (e, dt) {
                    dt.search('').draw();
                    $('#filter_kondisi, #filter_status').val('').trigger('change');
                    Swal.fire({ icon: 'success', title: 'Informasi', text: 'Selesai reload tabel ke kondisi awal', showConfirmButton: false, timer: 1300 })
                        .then(function () { dt.ajax.reload(null, true); });
                }
            },
            { extend: 'excelHtml5', exportOptions: { columns: ':not(.no-export)', orthogonal: 'export' } }
        ],
        columnDefs: [
            { targets: '_all', className: 'dt-head-center' },
            { targets: [0, 1, 7, 8], className: 'dt-body-center' },
            { targets: [3, 4, 5, 6], className: 'dt-body-right' },
            { targets: [3, 4, 5], orderable: false },
            { targets: [10, 11], render: function (data, type, row) { return CirebonwebFormat.Tanggal(data, 'waktu') } },
            { targets: 12, orderable: false }
        ]
    });

    $('#tabelData_filter.dataTables_filter').append($('#filter_kondisi, #filter_status'));

    $(document).on('change', '#filter_kondisi, #filter_status', function () {
        $tabelData.DataTable().ajax.reload(null, false);
    });

    $modalDiv
        .on('shown.bs.modal', function () { formCek.resetInitial(); })
        .on('hidden.bs.modal', function () { CirebonwebForm.FormReset(this); });
});

function simpan(id) {
    const $modalTitle = $('.modal-title'),
        $btnSubmit = $('#btnSubmit'),
        postUrl = `${urlThis}/simpan`;

    if (id > 0) {
        CirebonwebForm.FormFetch(`${urlThis}/getid`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;
            $modalTitle.text('Edit Data');
            $btnSubmit.text('Update');
            $('#id').val(response.data.id);
            $('#kode').val(response.data.kode);
            $('#nama').val(response.data.nama);
            $('#stok_masuk').val(CirebonwebFormat.Desimal(response.data.stok_masuk));
            $('#stok_pakai').val(CirebonwebFormat.Desimal(response.data.stok_pakai));
            $('#stok_sisa').val(CirebonwebFormat.Desimal(response.data.stok_sisa));
            $('#kondisi').val(response.data.kondisi);
            $('#status').val(response.data.status);
            $('#keterangan').val(response.data.keterangan);
            $modalDiv.modal('show');
        });
    }

    $formData.validate($.extend(CirebonwebForm.FormValidasi(), {
        rules: {
            kondisi: { required: true, digits: true },
            status: { required: true, digits: true },
            keterangan: { maxlength: 100 }
        },
        submitHandler: function () {
            if (!formCek.isChanged()) return false;
            CirebonwebForm.FormFetch(postUrl, $formData.serializeArray(), 'POST', {
                before_call: function () {
                    $btnSubmit.attr('disabled', true).html('<span class="spinner-border spinner-border-sm mr-1"></span> Loading...');
                },
                after_call: function () { $btnSubmit.attr('disabled', false).html('Simpan'); }
            }).done(function (response) {
                if (!response.success) return;
                $modalDiv.modal('hide');
                Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                    .then(function () { $tabelData.DataTable().ajax.reload(null, false); });
            });
            return false;
        }
    }));
}
